mapper.select:
select mcce.*,mn.p_name projectName
from multi_contract_con_ec mcce
left join pre_project mn on mn.p_id = mcce.project_id

    ${authSql}

and ec_change_type = #{ecChangeType}

    
        
            and likePname(#{projectName},mn.P_Id)=true
        
        
            and mn.p_name like concat('%',#{projectName},'%')
        
    


    and mn.p_Id=#{pId}

order by create_time desc

select coalesce(sum(
    case
        when pdc.opera_sign = '0' then -pdc.change_Declare_Money
        else pdc.change_Declare_Money
    end
), 0)
from pre_Design_Change pdc
left join pre_project mn on mn.p_id = pdc.pro_Id

    ${authSql}

and pdc.pro_Id = #{projectId}
and pdc.State = #{finishedState}
